package nx.updater;
import java.nio.file.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public final class UpdateService {
 private void log(String text){try{java.nio.file.Files.createDirectories(config.work);java.nio.file.Files.write(config.work.resolve("updater.log"),(System.currentTimeMillis()+" "+text+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8),java.nio.file.StandardOpenOption.CREATE,java.nio.file.StandardOpenOption.APPEND);}catch(Exception ex){}}
 public final UpdateConfig config;public volatile String status="NX Updater · sin comprobar";public volatile GitHubReleases.Offer offer;public volatile Path staged;public volatile long done,total,speed;public final AtomicBoolean cancel=new AtomicBoolean();public volatile boolean busy;private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"NX-Updater");t.setDaemon(true);return t;});
 public UpdateService(Path root)throws Exception{config=new UpdateConfig(root);}
 public synchronized void check(boolean force){if(busy)return;busy=true;worker.execute(()->{try{if(!config.configured()){offer=null;staged=null;status="NX Updater · "+config.configurationIssue();return;}status="NX Updater · buscando versiones";DownloadManager h=new DownloadManager(false);byte[] b=new GitHubReleases(h).query("https://api.github.com/repos/"+config.releaseRepository+"/releases?per_page=100",config.work.resolve("cache"),force);GitHubReleases.Offer previous=offer;offer=new GitHubReleases(h).select(b,config.platform,config.channel,config.installed,config.protocol,UpdateManifest.publicKey(config.trustedKey));if(offer==null||previous==null||!java.util.Arrays.equals(previous.raw,offer.raw)){staged=null;done=total=speed=0;}status=offer==null?"NX Updater · sin actualizaciones compatibles":"NX Updater · disponible "+offer.manifest.version;}catch(Exception e){status="NX Updater · "+e.getMessage();}finally{log(status);busy=false;}});}
 public synchronized void download(){if(busy||offer==null)return;busy=true;cancel.set(false);worker.execute(()->{try{staged=new UpdateInstaller(config).prepare(offer,new DownloadManager(false),cancel::get,(d,t,s,st)->{done=d;total=t;speed=s;status="NX Updater · "+st;});status="NX Updater · verificada y lista para instalar";}catch(Exception ex){status="NX Updater · "+ex.getMessage();}finally{log(status);busy=false;}});}
 public void launchHelper(String action)throws Exception{if(action.equals("install")&&staged==null)throw new IllegalStateException("No hay descarga verificada");Path helper=config.root.resolve("nx-updater.jar");if(!Files.isRegularFile(helper))throw new IllegalStateException("Falta el instalador externo local");Files.createDirectories(config.work);String java=Paths.get(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"java.exe":"java").toString();new ProcessBuilder(java,"-cp",helper.toString(),"nx.updater.UpdateInstaller",config.root.toString(),staged==null?"":staged.toString(),action).redirectErrorStream(true).redirectOutput(config.work.resolve("installer.log").toFile()).start();}
}
